def comp(g,bg):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in g]; out=[]
    for i in range(H):
        for j in range(W):
            if not seen[i][j] and g[i][j]!=bg:
                st=[(i,j)]; seen[i][j]=True; c=g[i][j]
                while st:
                    y,x=st.pop()
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==c:
                            seen[ny][nx]=True; st.append((ny,nx))
                cs=set(st)
                others={g[y][x] for y,x in cs}-{c}
                out.append((c,cs,others))
    return out
