def cells2(g,bg):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in g]; res=[]
    for i in range(H):
        for j in range(W):
            if not seen[i][j] and g[i][j]!=bg:
                st=[(i,j)]; seen[i][j]=True; col=g[i][j]; cells={(i,j)}
                while st:
                    y,x=st.pop()
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==col:
                            seen[ny][nx]=True; cells.add((ny,nx)); st.append((ny,nx))
                res.append((col,sorted(cells)))
    return res
