    H,W=len(inp),len(inp[0])
    bg=collections.Counter(v for r_ in inp for v in r_).most_common(1)[0][0]
    cs=comps(inp,bg); bigs=[c for c in cs if len(c['cells'])>1]; singles=[c for c in cs if len(c['cells'])==1]
    res=[r[:] for r in inp]
    for s in singles:
        scell=s['cells'][0]; col=s['color']
        best=min(bigs,key=lambda T:min(abs(a-b)+abs(c-d) for a,c in [scell] for b,d in T['cells']))
        T=best
        tr=[(p[0]-min(q[0] for q in T['cells']), p[1]-min(q[1] for q in T['cells'])) for p in T['cells']]
        th=max(p[0] for p,_ in tr); tw=max(_,p[1] for _,p in tr)
        h_,w_=th,tw
        cands=[]
        for name in ['id','vfl','hfl']:
            rr = tr if name=='id' else [(h_-r,c) for r,c in tr] if name=='vfl' else [(r,w_-c) for r,c in tr]
            rh=max(p[0] for p,_ in rr); rw=max(_,p[1] for _,p in rr)
            for r0 in range(-rh,H):
                for c0 in range(-rw,W):
                    cells=set()
                    ok=True
                    for r_,c_ in rr:
                        yy,xx=r0+r_,c0+c_
                        if not(0<=yy<H and 0<=xx<W) or res[yy][xx]!=bg: ok=False;break
                        cells.add((yy,xx))
                    if not ok: continue
                    if (scell[0],scell[1]) not in cells: continue
                    dist=min(abs(yy-a)+abs(xx-b) for yy,xx in cells for a,b in T['cells'])
                    cands.append((dist,len(cells)-1,name,r0,c0,sorted(cells)))
        cands.sort(key=lambda c:(c[0],-c[5]))
        _,_,nm,r0,c0,newcells=cands[0]
        for yy,xx in newcells: res[yy][xx]=col
    return res
